B.adO=new A.i(B.e,["Up to two weeks for the return to reach us and be processed, then 7 to 15 working days for a card refund to show.","\u0644\u062d\u062f \u0623\u0633\u0628\u0648\u0639\u064a\u0646 \u0644\u062d\u062f \u0645\u0627 \u0627\u0644\u0625\u0631\u062c\u0627\u0639 \u064a\u0648\u0635\u0644\u0646\u0627 \u0648\u064a\u062a\u0639\u0627\u0644\u062c\u060c \u0648\u0628\u0639\u062f\u0647\u0627 \u0645\u0646 7 \u0644\u0640 15 \u064a\u0648\u0645 \u0639\u0645\u0644 \u0644\u062d\u062f \u0645\u0627 \u0627\u0644\u0627\u0633\u062a\u0631\u062f\u0627\u062f \u064a\u0638\u0647\u0631 \u0639\u0644\u0649 \u0627\u0644\u0628\u0637\u0627\u0642\u0629."],t.w)
