B.acB=new A.i(B.e,["Products and prices","\u0627\u0644\u0645\u0646\u062a\u062c\u0627\u062a \u0648\u0627\u0644\u0623\u0633\u0639\u0627\u0631"],t.w)
B.adi=new A.i(B.e,["Quantities can be limited, and a product can sell out while you are looking at it.","\u0627\u0644\u0643\u0645\u064a\u0627\u062a \u0645\u0645\u0643\u0646 \u062a\u0643\u0648\u0646 \u0645\u062d\u062f\u0648\u062f\u0629\u060c \u0648\u0627\u0644\u0642\u0637\u0639\u0629 \u0645\u0645\u0643\u0646 \u062a\u062e\u0644\u0635 \u0648\u0627\u0646\u062a \u0628\u062a\u062a\u0641\u0631\u062c \u0639\u0644\u064a\u0647\u0627."],t.w)
B.aeE=new A.i(B.e,["We show product photographs as accurately as we can, but colours vary between screens.","\u0628\u0646\u0639\u0631\u0636 \u0635\u0648\u0631 \u0627\u0644\u0645\u0646\u062a\u062c\u0627\u062a \u0628\u0623\u062f\u0642 \u0634\u0643\u0644 \u0645\u0645\u0643\u0646\u060c \u0644\u0643\u0646 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0628\u062a\u062e\u062a\u0644\u0641 \u0645\u0646 \u0634\u0627\u0634\u0629 \u0644\u0644\u062a\u0627\u0646\u064a\u0629."],t.w)
B.aaq=new A.i(B.e,["We may correct an error in a price or a description, and cancel an order placed on it.","\u0645\u0645\u0643\u0646 \u0646\u0635\u062d\u062d \u062e\u0637\u0623 \u0641\u064a \u0627\u0644\u0633\u0639\u0631 \u0623\u0648 \u0627\u0644\u0648\u0635\u0641\u060c \u0648\u0646\u0644\u063a\u064a \u0637\u0644\u0628 \u0627\u062a\u0639\u0645\u0644 \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u064a\u0647."],t.w)
